118	CollisionPoint PhysicsCollisionPair::getContactPoint(int index) const
119	{
120	    CollisionPoint point = {};
121	
122	    int count = getContactCount();
123	    if (index < 0 || index >= count)
124	    {
125	        return point;
126	    }
127	
128	    point.pointA = PhysicsHelper::cpv2point(cpArbiterGetPointA(_arbiter, index));
129	    point.pointB = PhysicsHelper::cpv2point(cpArbiterGetPointB(_arbiter, index));
130	    point.normal = PhysicsHelper::cpv2point(cpArbiterGetNormal(_arbiter));
131	    point.depth = PhysicsHelper::cpfloat2float(cpArbiterGetDepth(_arbiter, index));
132	
133	    // Chipmunk only exposes the accumulated impulse for the whole arbiter, so it is
134	    // shared out evenly between the contact points.
135	    float share = 1.0f / static_cast<float>(count);
136	    point.normalImpulse = getTotalNormalImpulse() * share;
137	    point.tangentImpulse = getTotalTangentImpulse() * share;
138	
139	    return point;
140	}
