142	void PhysicsCollisionPair::getContactPoints(CollisionPoint* outPoints, int* outCount) const
143	{
144	    int count = 0;
145	
146	    if (outPoints != nullptr)
147	    {
148	        count = getContactCount();
149	        for (int i = 0; i < count; ++i)
150	        {
151	            outPoints[i] = getContactPoint(i);
152	        }
153	    }
154	
155	    if (outCount != nullptr)
156	    {
157	        *outCount = count;
158	    }
159	}
